<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,shallowRef,watch} from 'vue';
import type {AiAnnotationCreateContext} from '../types/ai-annotation-create';
import ReadOnlyFacts from '../components/ReadOnlyFacts.vue';
const props=defineProps<{context:AiAnnotationCreateContext}>(),s=shallowRef(props.context.snapshot());
const scrollBody=ref<HTMLElement>(),materials=ref<HTMLElement>(),configuration=ref<HTMLElement>(),advanced=ref<HTMLElement>(),hydration=ref<HTMLElement>(),confirmation=ref<HTMLElement>(),footer=ref<HTMLElement>(),recovery=ref<HTMLElement>();
const steps=[{id:1,title:'素材范围',description:'选择图片与跨页范围'},{id:2,title:'模型与配置',description:'模型、标签、Prompt / Query'},{id:3,title:'核对与创建',description:'确认范围与实际推理配置'}];
const disabled=computed(()=>Boolean(s.value.busy)||props.context.signal.aborted);
const protocol=computed(()=>s.value.inferenceProtocol==='wevisone_detection'?'WeVisOne Detection Query':s.value.inferenceProtocol==='generic_prompt'?'通用视觉 Prompt':'以已选模型的配置为准');
watch(()=>s.value.step,()=>void nextTick(()=>{if(scrollBody.value)scrollBody.value.scrollTop=0}));
let alive=true,stop:(()=>void)|undefined;
const nodes:HTMLElement[]=[];
function dispose(){stop?.();stop=undefined;for(const node of nodes){if([materials.value,configuration.value,advanced.value,hydration.value,confirmation.value,footer.value,recovery.value].some(host=>host?.contains(node)))node.remove()}nodes.length=0;props.context.signal.removeEventListener('abort',dispose)}
onMounted(()=>{
 if(props.context.signal.aborted)return;
 const bindings:[[HTMLElement|undefined,HTMLElement|undefined],...[HTMLElement|undefined,HTMLElement|undefined][]]=[[materials.value,props.context.slots.materials],[configuration.value,props.context.slots.configuration],[advanced.value,props.context.slots.advanced],[hydration.value,props.context.slots.hydration],[confirmation.value,props.context.slots.confirmation],[footer.value,props.context.slots.footer],[recovery.value,props.context.slots.recovery]];
 for(const [host,node] of bindings)if(host&&node){host.appendChild(node);nodes.push(node)}
 stop=props.context.subscribe(value=>{if(alive&&!props.context.signal.aborted)s.value=value});
 props.context.signal.addEventListener('abort',dispose,{once:true});
});
onBeforeUnmount(()=>{alive=false;dispose()});
</script>
<template><section class="vue-ai-annotation-create" aria-label="AI 标注创建工作台" :aria-busy="s.busy||s.loading">
 <header class="create-heading"><div><small>智能标注 / 创建任务</small><h2>{{ s.taskName||'创建 AI 标注任务' }}</h2><p>项目 {{ s.projectId }}</p></div><div class="heading-actions"><el-button :disabled="disabled" @click="context.actions.legacy()">使用原创建界面</el-button><el-button :disabled="context.signal.aborted" @click="context.actions.close()">关闭</el-button></div></header>
 <nav class="create-steps" aria-label="AI 标注创建步骤"><el-button v-for="item in steps" :key="item.id" :type="s.step===item.id?'primary':'default'" :aria-current="s.step===item.id?'step':undefined" :disabled="disabled" @click="context.actions.step(item.id)"><span class="step-index">{{ item.id }}</span><span><strong>{{ item.title }}</strong><small>{{ item.description }}</small></span></el-button></nav>
 <div ref="scrollBody" class="create-scroll"><div ref="hydration" class="hydration-slot" data-ai-annotation-create-slot="hydration"></div><div v-if="s.error" class="create-message error" role="alert">{{ s.error }}</div>
  <div v-if="s.pending" class="create-message pending" role="status"><strong>创建结果待核验</strong><p>{{ s.pending.message||'请先查询已有请求的结果，再决定后续操作。' }}</p><details v-if="s.pending.requestId||s.pending.state"><summary>请求记录</summary><ReadOnlyFacts :fields="[['请求 ID',s.pending.requestId],['状态',s.pending.state]]"/></details></div>
  <div class="create-layout"><main class="create-main">
   <section v-show="s.step===1" class="create-step" aria-label="待标注素材范围"><div ref="materials" data-ai-annotation-create-slot="materials"></div></section>
   <section v-show="s.step===2" class="create-step" aria-label="模型服务标签与推理配置"><div class="protocol-note"><strong>{{ protocol }}</strong><p v-if="s.inferenceProtocol==='wevisone_detection'">本任务使用模型配置中的 Detection Query；通用 Prompt 不参与该服务推理。</p></div><div ref="configuration" data-ai-annotation-create-slot="configuration"></div><div ref="advanced" data-ai-annotation-create-slot="advanced"></div></section>
   <section v-show="s.step===3" class="create-step" aria-label="AI 标注最终核对"><div class="confirmation-heading"><h3>核对本次任务</h3><p>{{ s.confirmationReady?'请核对下方实际提交配置后明确确认。':'请先在底栏核对当前配置，确认素材范围、模型服务与标签。' }}</p></div><div ref="confirmation" data-ai-annotation-create-slot="confirmation"></div></section>
  </main><aside class="create-summary" aria-label="当前 AI 标注配置摘要"><h3>本次任务</h3><ReadOnlyFacts :fields="[['任务名称',s.taskName],['已选素材',s.selectedCount],['已核对素材',s.confirmedCount],['冻结范围数量',s.frozenCount],['跨页排除数量',s.excludedCount],['模型服务',s.modelName],['提供方',s.providerName],['推理协议',protocol],['置信度阈值',s.threshold],['参考图数量',s.referenceCount],['标签',s.labelCodes===undefined?undefined:s.labelCodes.length?s.labelCodes.join('、'):'尚未选择']]"/>
   <p class="summary-note">任务生成候选结果，人工审核后才写入正式标注。</p><details v-if="s.selectionRef||s.detectionQueries?.length" class="technical-evidence"><summary>范围与查询明细</summary><ReadOnlyFacts v-if="s.selectionRef" :fields="[['冻结选择引用',s.selectionRef]]"/><dl v-if="s.detectionQueries?.length"><template v-for="(row,index) in s.detectionQueries" :key="index"><dt>{{ row.code }}</dt><dd>{{ row.query }}<small v-if="row.source">{{ row.source }}</small></dd></template></dl></details>
  </aside></div><div ref="recovery" data-ai-annotation-create-slot="recovery"></div><p v-if="s.status" class="create-message" role="status">{{ s.status }}</p>
 </div>
 <footer ref="footer" class="create-footer" data-ai-annotation-create-slot="footer" aria-label="原 AI 标注创建操作"></footer>
</section></template>
<style scoped>
:global(.ai-create-workbench[data-vue-ai-create="true"]){display:block!important;grid-template-columns:none!important;grid-template-rows:none!important;gap:0!important;padding:0!important;min-width:0}.vue-ai-annotation-create{display:flex;flex-direction:column;width:100%;min-width:0;min-height:0;max-height:calc(100dvh - 150px);background:var(--el-bg-color,#fff);color:var(--el-text-color-primary,#303133);grid-column:1/-1;overflow:hidden}.create-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:16px 20px;border-bottom:1px solid var(--el-border-color-lighter,#ebeef5);flex-shrink:0}.create-heading h2{font-size:19px;margin:5px 0;overflow-wrap:anywhere}.create-heading small,.create-heading p{font-size:12px;margin:0;color:var(--el-text-color-secondary,#777)}.heading-actions{display:flex;gap:8px;flex-wrap:wrap}.heading-actions :deep(.el-button){margin:0}.create-steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:12px 20px;border-bottom:1px solid var(--el-border-color-lighter,#ebeef5);flex-shrink:0}.create-steps :deep(.el-button){margin:0;padding:10px;height:auto;justify-content:flex-start;text-align:left}.create-steps :deep(.el-button>span){display:flex;gap:10px;align-items:center;white-space:normal}.create-steps strong{display:block;font-size:13px}.create-steps small{display:block;font-size:11px;margin-top:4px;font-weight:400;line-height:1.5}.step-index{font-size:18px;min-width:18px}.create-scroll{overflow:auto;min-height:0;flex:1}.create-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(240px,285px);gap:18px;align-items:start;padding:18px;background:var(--el-fill-color-lighter,#fafafa)}.create-main,.create-step{min-width:0}.create-step :deep(.ai-create-configuration){display:block;width:100%;padding:0;min-width:0}.create-step :deep(.ai-create-section),.create-step :deep(.ai-create-advanced){margin:0 0 14px;max-width:100%;min-width:0}.create-step :deep(input),.create-step :deep(select),.create-step :deep(textarea){max-width:100%;box-sizing:border-box}.create-step :deep(.ai-create-models){grid-template-columns:repeat(auto-fit,minmax(min(240px,100%),1fr))}.create-step :deep(.ai-create-label-grid){max-height:350px;overflow:auto}.create-step :deep(pre){white-space:pre-wrap;overflow-wrap:anywhere;max-width:100%}.hydration-slot:empty{display:none}.hydration-slot :deep(.ai-create-hydration){margin:10px 18px}.create-summary{padding:15px;border:1px solid var(--el-border-color-lighter,#ebeef5);border-radius:8px;background:var(--el-bg-color,#fff);min-width:0;overflow-wrap:anywhere}.create-summary h3{font-size:15px;margin:0 0 12px}.create-summary :deep(.readonly-facts){font-size:12px;grid-template-columns:minmax(90px,.8fr) minmax(0,1.2fr);gap:8px}.summary-note{font-size:12px;line-height:1.7;color:var(--el-text-color-secondary,#777)}.technical-evidence{padding-top:10px;border-top:1px solid var(--el-border-color-lighter,#ebeef5);font-size:12px}.technical-evidence summary{cursor:pointer;margin-bottom:10px}.technical-evidence dl{display:grid;grid-template-columns:minmax(60px,.6fr) minmax(0,1.4fr);gap:8px}.technical-evidence dd{margin:0;overflow-wrap:anywhere}.technical-evidence dd small{display:block;margin-top:4px;color:var(--el-text-color-secondary,#777)}.protocol-note,.confirmation-heading{border:1px solid var(--el-border-color-lighter,#ebeef5);border-radius:8px;padding:12px;margin-bottom:14px;background:var(--el-bg-color,#fff);font-size:13px}.protocol-note p,.confirmation-heading p{margin:5px 0 0;line-height:1.6;color:var(--el-text-color-secondary,#777)}.confirmation-heading h3{font-size:16px;margin:0}.create-message{padding:10px 18px;font-size:13px;line-height:1.6;overflow-wrap:anywhere;margin:0}.create-message p{margin:5px 0}.error{color:var(--el-color-danger,#f56c6c);background:var(--el-color-danger-light-9,#fef0f0)}.pending{background:var(--el-color-warning-light-9,#fdf6ec)}.create-footer{padding:12px 18px;border-top:1px solid var(--el-border-color-lighter,#ebeef5);flex-shrink:0;background:var(--el-bg-color,#fff)}.create-footer :deep(.ai-create-footer){margin:0;padding:0;border:0;display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.create-footer :deep(.row){flex-wrap:wrap}.create-footer :deep(.btn){white-space:normal}.create-footer:empty{display:none}
@media(max-width:1000px){.create-layout{grid-template-columns:minmax(0,1fr) 235px;gap:12px;padding:12px}.create-summary{padding:12px}.create-heading{padding:12px}.create-steps{padding:10px 12px}.create-steps small{display:none}}
@media(max-width:760px){.vue-ai-annotation-create{max-height:calc(100dvh - 125px)}.create-layout{grid-template-columns:minmax(0,1fr)}.create-heading{flex-wrap:wrap;gap:8px}.create-heading h2{font-size:16px}.create-steps{gap:6px}.create-steps :deep(.el-button){padding:8px 5px}.create-steps :deep(.el-button>span){gap:5px}.create-steps strong{font-size:12px}.step-index{font-size:15px;min-width:14px}.create-step :deep(.form.two){grid-template-columns:minmax(0,1fr)}.create-footer{padding:10px 12px}.create-footer :deep(.ai-create-footer>span){font-size:12px}}
</style>
